do $release$ declare payload jsonb:='{"batch":"nl-scale-20261102-045","project":"qvplwejffhjvxaypmjut","actions":[{"ref":"a1","relation":"authors","key":{"open_library_id":"OL15497362A"},"before":null,"after":{"name":"Stella Bergsma","open_library_id":"OL15497362A"}},{"ref":"w0","relation":"works","key":{"native_identity_key":"nlscale:20261102:ol:OL13752009W"},"before":null,"after":{"title":"Baba Jaga je snijela jaje","author_id":3168,"first_publish_year":null,"open_library_id":"OL13752009W","cover_id":null,"source_type":"open_library","work_type":"novel","native_identity_key":"nlscale:20261102:ol:OL13752009W"}},{"ref":"e0","relation":"editions","key":{"open_library_edition_id":"OL58467777M"},"before":null,"after":{"work_id":"@w0","open_library_edition_id":"OL58467777M","isbn_13":"9789023458920","isbn_10":null,"title":"Baba Jaga legde een ei","language":"dut","publisher":"De Bezige Bij"}},{"ref":"d0","relation":"catalog_work_descriptions","key":{"work_id":"@w0","language":"nl"},"before":null,"after":{"work_id":"@w0","language":"nl","bound_author_id":3168,"text":"Een reis naar Varna, de stad van de moeder van de vertelster, staat naast het verblijf van drie oudere vrouwen in een Tsjechisch kuuroord. Op het eerste gezicht lijken deze gebeurtenissen weinig te maken te hebben met Baba Jaga, de heks uit de Slavische overlevering. De roman brengt de verhalen in verschillende delen met elkaar in verband. Een beschouwing over de mythische figuur verandert vervolgens de blik op het voorafgaande. Ouder worden en de kracht van vertellen vormen daarbij terugkerende vragen.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://www.uitgeverijathenaeum.nl/nijgh-van-ditmar/boek/baba-jaga-legde-een-ei/","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p328252220"],"reference":"new-work-dossier-readings-045.json#113","checked_at":"2026-11-03T09:13:56.273Z","note":"BabaJa